<?php
/** New-store C2S replies, reusing the independent Community admission fixture. */
defined( 'ABSPATH' ) || exit( 1 );
$prepare = $community_reply_prepare ?? 'axismundi_act_prepare_community_reply';
$reply_review = $community_reply_review ?? 'axismundi_act_review_community_post';
$inboxes = $community_reply_inboxes ?? 'axismundi_activitypub_bridge_activity_inboxes';
$community_reply_check = static function ( $group, $people, $users, $root, $remote_person, $prefix, &$objects, &$actors ) use ( $prepare, $reply_review, $inboxes ) {
	global $wpdb;
	$count = 0;
	$check = static function ( $ok, $label ) use ( &$count ) { if ( ! $ok ) { throw new RuntimeException( $label ); } ++$count; };
	$public = 'https://www.w3.org/ns/activitystreams#Public';
	$note = array( 'type' => 'Note', 'content' => '<p>Community reply</p>', 'inReplyTo' => $root['object']['id'], 'to' => array( $public ) );
	axismundi_act_write_relation( 'follow', $people[0]->get_uri(), $group->get_uri(), 'outbound', 'accepted', null, null );
	$prepared = $prepare( $note, $people[0] );
	$check( is_array( $prepared ) && ( $prepared['audience'] ?? '' ) === $group->get_uri(), 'Reply context resolves the accepted Community' );
	$check( $prepared['to'] === array( $group->get_uri() ) && in_array( $public, $prepared['cc'], true ) && in_array( $remote_person->get_uri(), $prepared['cc'], true ), 'Reply addressing preserves Group to and parent author cc' );
	$comments_before = (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$wpdb->comments}" );
	$posts_before = (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$wpdb->posts}" );
	$created = axismundi_act_submit_outbox( $users[0], $people[0], $note, 'community-reply-' . $prefix );
	$check( $created instanceof Axismundi_Activity, 'C2S creates a Community Note in the new store' );
	$uri = $created->get_object_uri(); $objects[] = $uri;
	$row = axismundi_op_get_local_object( $uri );
	$check( $row && $row['document']['audience'] === $group->get_uri() && $row['document']['inReplyTo'] === $root['object']['id'], 'OP body preserves reply identity and Community' );
	$check( is_array( $created->get_payload()['object'] ) && $created->get_payload()['object']['attributedTo'] === $people[0]->get_uri(), 'Community Create retains an immutable Person Note snapshot' );
	$check( 'pending' === axismundi_actors_get_community_post( $group->get_identity_id(), $uri )['admission_state'] && array() === axismundi_act_get_by_object( $created->get_uri() ), 'Local replies wait for existing Community moderation' );
	$announced = $reply_review( $users[0], $people[0], $group, $uri, true );
	$check( $announced instanceof Axismundi_Activity && 'Announce' === $announced->get_type() && $announced->get_actor_uri() === $group->get_uri() && $announced->get_payload()['object'] === $created->get_payload(), 'Local reply becomes Group Announce only after approval' );
	$check( $uri === axismundi_act_submit_outbox( $users[0], $people[0], $note, 'community-reply-' . $prefix )->get_object_uri(), 'Local reply retry reuses the same Object' );
	$check( $root['object']['id'] === $wpdb->get_var( $wpdb->prepare( 'SELECT parent_uri FROM %i WHERE child_uri=%s', axismundi_op_thread_edges_table(), $uri ) ), 'C2S reply edge uses Object URIs without CPTs' );
	$check( null === apply_filters( 'axismundi_act_public_outbox_payload', $created->get_payload(), $created ), 'Community submission stays out of the personal public outbox' );
	$incoming_uri = $prefix . '/received-comment'; $objects[] = $incoming_uri;
	$incoming = array( 'id' => $incoming_uri . '/create', 'type' => 'Create', 'actor' => $remote_person->get_uri(), 'to' => array( $group->get_uri() ), 'cc' => array( $public ), 'object' => array( 'id' => $incoming_uri, 'type' => 'Note', 'attributedTo' => $remote_person->get_uri(), 'inReplyTo' => $root['object']['id'], 'audience' => $remote_person->get_uri(), 'cc' => array( $public, $group->get_uri() ), 'content' => 'Incoming reply' ) );
	$received_comment = axismundi_activitypub_bridge_record_inbox( $incoming, array(), false, $group );
	$check( $received_comment instanceof Axismundi_Activity && 'pending' === axismundi_actors_get_community_post( $group->get_identity_id(), $incoming_uri )['admission_state'], 'Incoming parent-author audience and Group cc remain accepted' );
	$forged_uri = $prefix . '/unaccepted-parent'; $objects[] = $forged_uri;
	axismundi_op_store_remote_object( array( 'id' => $forged_uri, 'type' => 'Page', 'attributedTo' => $remote_person->get_uri(), 'audience' => $group->get_uri(), 'to' => array( $public ), 'name' => 'Unaccepted', 'content' => 'Claim only' ) );
	$forged = $note; $forged['inReplyTo'] = $forged_uri;
	$check( is_wp_error( $prepare( $forged, $people[0] ) ), 'A parent Group claim alone cannot publish a local Community reply' );
	$remote_group_uri = $prefix . '/remote-community';
	$normalized = axismundi_actors_normalize_remote_actor_payload( array( 'id' => $remote_group_uri, 'type' => 'Group', 'preferredUsername' => 'remotecommunity', 'inbox' => $remote_group_uri . '/inbox', 'outbox' => $remote_group_uri . '/outbox' ), $remote_group_uri );
	$remote_group = axismundi_actors_upsert_remote( $normalized );
	$check( $remote_group instanceof Axismundi_Actor, 'Remote Community fixture is cached without platform inference' );
	$actors[] = $remote_group;
	$parent = $prefix . '/remote-comment'; $objects[] = $parent;
	// Receive either shape: this is not our outbound audience contract.
	$stored = axismundi_op_store_remote_object( array( 'id' => $parent, 'type' => 'Note', 'attributedTo' => $remote_person->get_uri(), 'audience' => $remote_person->get_uri(), 'to' => array( $public ), 'cc' => array( $remote_group_uri, $remote_person->get_uri() ), 'inReplyTo' => $prefix . '/remote-page', 'content' => 'Incoming Comment' ) );
	$check( is_array( $stored ), 'Lemmy-shaped incoming Comment is cached' );
	$note['inReplyTo'] = $parent;
	$out = axismundi_act_submit_outbox( $users[0], $people[0], $note );
	$check( $out instanceof Axismundi_Activity, 'C2S replies to remote Community without a Follow prerequisite' );
	$objects[] = $out->get_object_uri();
	$payload = $out->get_payload();
	$check( ( $payload['object']['audience'] ?? '' ) === $remote_group_uri && $payload['to'] === array( $remote_group_uri ) && in_array( $remote_person->get_uri(), $payload['cc'], true ) && in_array( $public, $payload['cc'], true ), 'Remote reply uses the established outbound addressing' );
	$check( array( $remote_group_uri . '/inbox' ) === $inboxes( $out ), 'Remote reply delivers only to the Community Inbox' );
	$page = $prefix . '/remote-page'; $objects[] = $page;
	axismundi_op_store_remote_object( array( 'id' => $page, 'type' => 'Page', 'attributedTo' => $remote_person->get_uri(), 'audience' => $remote_group_uri, 'to' => array( $public ), 'name' => 'Remote Page', 'content' => 'Page body' ) );
	$note['inReplyTo'] = $page;
	$page_reply = axismundi_act_submit_outbox( $users[0], $people[0], $note );
	$check( $page_reply instanceof Axismundi_Activity && $page_reply->get_payload()['object']['audience'] === $remote_group_uri && array( $remote_group_uri . '/inbox' ) === $inboxes( $page_reply ), 'Remote Page reply uses Community-only delivery too' );
	$objects[] = $page_reply->get_object_uri();
	$delete = axismundi_act_submit_outbox( $users[0], $people[0], array( 'type' => 'Delete', 'actor' => $people[0]->get_uri(), 'object' => $page_reply->get_object_uri() ) );
	$check( $delete instanceof Axismundi_Activity && array( $remote_group_uri . '/inbox' ) === $inboxes( $delete ), 'Deleting a Community reply cannot fan out to personal followers' );
	$private = $note; $private['to'] = array( $remote_person->get_uri() );
	$check( $private === $prepare( $private, $people[0] ), 'Private replies are never broadened into public Community submissions' );
	$check( (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$wpdb->comments}" ) === $comments_before && (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$wpdb->posts}" ) === $posts_before, 'Replies create neither WordPress posts nor comments' );
	// Restore the relation snapshot expected by the enclosing fixture without modifying other relations.
	$wpdb->query( $wpdb->prepare( 'DELETE FROM %i WHERE subject_actor_uri=%s AND object_actor_uri=%s', axismundi_act_relations_table(), $people[0]->get_uri(), $group->get_uri() ) );
	return $count;
};
require __DIR__ . '/audit-community-posts.php';
